CREATE TABLE orders (
  order_id        NUMBER        PRIMARY KEY,
  customer_id     NUMBER        NOT NULL,
  customer_email  VARCHAR2(100) NOT NULL,
  order_date      DATE          NOT NULL,
  status          VARCHAR2(10)  NOT NULL,
  quantity        NUMBER        NOT NULL,
  unit_price      NUMBER(10,2)  NOT NULL
);

