CREATE INDEX ord_day_ix ON orders (TRUNC(order_date));

SELECT order_id, order_date
  FROM orders
 WHERE TRUNC(order_date) = DATE '2026-10-21';

CREATE INDEX ord_value_ix ON orders (quantity * unit_price);

SELECT order_id, quantity * unit_price AS order_value
  FROM orders
 WHERE quantity * unit_price > 1000;

CREATE INDEX ord_pending_ix
  ON orders (CASE status WHEN 'PENDING' THEN customer_id END);

SELECT order_id, customer_id
  FROM orders
 WHERE CASE status WHEN 'PENDING' THEN customer_id END = 102;

CREATE OR REPLACE FUNCTION email_domain (p_email IN VARCHAR2)
  RETURN VARCHAR2
  DETERMINISTIC
IS
BEGIN
  RETURN LOWER(SUBSTR(p_email, INSTR(p_email, '@') + 1));
END email_domain;
/

CREATE INDEX ord_domain_ix ON orders (email_domain(customer_email));

SELECT COUNT(*) AS orders_from_domain
  FROM orders
 WHERE email_domain(customer_email) = 'example.com';

SELECT index_name, column_expression
  FROM user_ind_expressions
 WHERE table_name = 'ORDERS';

SELECT index_name, status, funcidx_status, visibility
  FROM user_indexes
 WHERE table_name = 'ORDERS';

ALTER TABLE orders ADD (
  email_upper VARCHAR2(100) GENERATED ALWAYS AS (UPPER(customer_email)) VIRTUAL
);

CREATE INDEX ord_email_upper_vx ON orders (email_upper);

SELECT order_id FROM orders WHERE email_upper = 'PRIYA.N@EXAMPLE.COM';

